        (, bytes memory data) = TARGET.staticcall(abi.encodeWithSignature("_swapAndLiquifyEnabled()"));
        bool swapEnabled = abi.decode(data, (bool));
        require(!swapEnabled, "swapAndLiquifyEnabled should be false");

        // Fixed: Use the decoded value instead of the undeclared identifier
